<?php declare(strict_types=1); namespace Annam; $title='Create booking'; ?>
<form method="post" class="o-form"><?= csrf() ?><input type="hidden" name="token" value="<?= e($token) ?>"><section class="o-card"><h2>Customer & delivery</h2><div class="o-grid-form"><label class="o-field">Mobile number<input name="phone" id="customer-phone" type="tel" value="<?= e($conversation['phone']??'') ?>" required maxlength="20"></label><label class="o-field">Name<input name="name" id="customer-name" value="<?= e($conversation['display_name']??'') ?>" required maxlength="120"></label><label class="o-field">Fulfilment<select name="fulfilment_method" id="customer-fulfilment_method"><option value="local">Local delivery / collection</option><option value="courier">Courier outside Chennai (Snacks only)</option></select></label><?php foreach(['city'=>'City','state'=>'State','country'=>'Country','postal_code'=>'Postal code'] as $k=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($k) ?>" id="customer-<?= e($k) ?>" value="<?= e(['state'=>'Tamil Nadu','country'=>'India'][$k]??'') ?>"></label><?php endforeach; ?><label class="o-field">Delivery date<input type="date" name="delivery_date" value="<?= e(date('Y-m-d')) ?>"></label><p id="customer-lookup-status" role="status"></p><label class="o-field">Channel<select name="channel"><option value="manual">Manual booking</option><option value="whatsapp" <?= $conversation?'selected':'' ?>>WhatsApp booking</option></select></label><label class="o-field">Payment<select name="payment_method"><option value="manual">Manual payment</option><option value="cod">Cash on delivery</option></select></label><label class="o-field">Delivery area<select name="zone_id" id="customer-zone"><option value="">Collection at kitchen</option><?php foreach($zones as $zone): ?><option value="<?= e($zone['id']) ?>"><?= e($zone['pincode'].' · '.$zone['area_name']) ?> (<?= money($zone['delivery_fee']) ?>)</option><?php endforeach; ?></select></label><label class="o-field">Delivery address<textarea name="address" id="customer-address" maxlength="2000"></textarea></label></div></section><section class="o-card"><h2>Choose items</h2><input id="booking-filter" placeholder="Search dishes & products" type="search"><div class="php-booking-items"><?php foreach($items as $item): if(!$item['active'])continue; ?><label class="php-booking-item"><span><?= e($item['name']) ?> <small><?= money($item['price']) ?></small></span><select name="meals[<?= e($item['id']) ?>]" aria-label="Food category for <?= e($item['name']) ?>"><?php foreach(($item['fulfilment']==='courier'?['snacks']:($assignedMeals[$item['id']]??['unclassified','breakfast','lunch','dinner','snacks'])) as $key): ?><option value="<?= e($key) ?>"><?= e(ucfirst($key)) ?></option><?php endforeach; ?></select><input type="number" name="quantities[<?= e($item['id']) ?>]" min="0" max="999" placeholder="0" aria-label="Quantity for <?= e($item['name']) ?>"></label><?php endforeach; ?></div></section><button class="o-btn o-btn-primary">Create unpaid booking</button></form><script src="/assets/customer-lookup.js" defer></script><script src="/assets/workflow.js" defer></script>
